    public void handleBalance(Client client, Object message)
    {
        //
        // spot order fill
        //     {
        //         "time": 1653664351,
        //         "time_ms": 1605248616763,
        //         "channel": "spot.balances",
        //         "event": "update",
        //         "result": [
        //             {
        //                 "timestamp": "1667556323",
        //                 "timestamp_ms": "1667556323730",
        //                 "user": "1000001",
        //                 "currency": "USDT",
        //                 "change": "0",
        //                 "total": "222244.3827652",
        //                 "available": "222244.3827",
        //                 "freeze": "5",
        //                 "freeze_change": "5.000000",
        //                 "change_type": "order-create"
        //             }
        //         ]
        //     }
        //
        // account transfer
        //
        //    {
        //        "id": null,
        //        "time": 1653665088,
        //        "channel": "futures.balances",
        //        "event": "update",
        //        "error": null,
        //        "result": [
        //          {
        //            "balance": 25.035008537,
        //            "change": 25,
        //            "text": "-",
        //            "time": 1653665088,
        //            "time_ms": 1653665088286,
        //            "type": "dnw",
        //            "user": "10406147"
        //          }
        //        ]
        //   }
        //
        // swap order fill
        //   {
        //       "id": null,
        //       "time": 1653665311,
        //       "channel": "futures.balances",
        //       "event": "update",
        //       "error": null,
        //       "result": [
        //         {
        //           "balance": 20.031873037,
        //           "change": -0.0031355,
        //           "text": "LTC_USDT:165551103273",
        //           "time": 1653665311,
        //           "time_ms": 1653665311437,
        //           "type": "fee",
        //           "user": "10406147"
        //         }
        //       ]
        //   }
        //
        Object result = this.safeValue(message, "result", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Helpers.addElementToObject(this.balance, "info", result);
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(result)); i++)
        {
            Object rawBalance = Helpers.GetValue(result, i);
            Object account = this.account();
            Object currencyId = this.safeString(rawBalance, "currency", "USDT"); // when not present it is USDT
            Object code = this.safeCurrencyCode(currencyId);
            Object timestamp = this.safeInteger2(rawBalance, "time_ms", "timestamp_ms");
            Helpers.addElementToObject(this.balance, "timestamp", timestamp);
            Helpers.addElementToObject(this.balance, "datetime", this.iso8601(timestamp));
            Helpers.addElementToObject(account, "used", this.safeString(rawBalance, "freeze"));
            Helpers.addElementToObject(account, "free", this.safeString(rawBalance, "available"));
            Helpers.addElementToObject(account, "total", this.safeString2(rawBalance, "total", "balance"));
            if (Helpers.isTrue(!Helpers.isEqual(code, null)))
            {
                Helpers.addElementToObject(this.balance, code, account);
            }
        }
        Object channel = ((String)this.safeString(message, "channel"));
        Object parts = Helpers.split(channel, ".");
        Object rawType = this.safeString(parts, 0);
        Object channelType = this.getSupportedMapping(rawType, new java.util.HashMap<String, Object>() {{
            put( "spot", "spot" );
            put( "futures", "swap" );
            put( "options", "option" );
        }});
        Object messageHash = Helpers.add(channelType, ".balance");
        this.balance = this.safeBalance(this.balance);
        client.resolve(this.balance, messageHash);
    }

    /**
     * @method
     * @name gate#watchPositions
     * @see https://www.gate.io/docs/developers/futures/ws/en/#positions-subscription
     * @see https://www.gate.io/docs/developers/delivery/ws/en/#positions-subscription
     * @see https://www.gate.io/docs/developers/options/ws/en/#positions-channel
     * @description watch all open positions
     * @param {string[]} [symbols] list of unified market symbols to watch positions for
     * @param {int} [since] the earliest time in ms to fetch positions for
     * @param {int} [limit] the maximum number of positions to retrieve
     * @param {object} params extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/en/latest/manual.html#position-structure}
     */
    public java.util.concurrent.CompletableFuture<java.util.List<io.github.ccxt.types.Position>> watchPositions(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbols = Helpers.getArg(optionalArgs, 0, null);
            Object since = Helpers.getArg(optionalArgs, 1, null);
            Object limit = Helpers.getArg(optionalArgs, 2, null);
            Object parameters = Helpers.getArg(optionalArgs, 3, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = null;
            symbols = this.marketSymbols(symbols);
            Object payload = new java.util.ArrayList<Object>(java.util.Arrays.asList(Helpers.add("!", "all")));
            if (!Helpers.isTrue(this.isEmpty(symbols)))
            {
                market = this.getMarketFromSymbols(symbols);
            }
            Object type = null;
            Object query = null;
            var typequeryVariable = this.handleMarketTypeAndParams("watchPositions", market, parameters);
            type = ((java.util.List<Object>) typequeryVariable).get(0);
            query = ((java.util.List<Object>) typequeryVariable).get(1);
            if (Helpers.isTrue(Helpers.isEqual(type, "spot")))
            {
                type = "swap";
            }
            Object typeId = this.getSupportedMapping(type, new java.util.HashMap<String, Object>() {{
                put( "future", "futures" );
                put( "swap", "futures" );
                put( "option", "options" );
            }});
            Object messageHash = Helpers.add(type, ":positions");
            if (!Helpers.isTrue(this.isEmpty(symbols)))
            {
                if (Helpers.isTrue(Helpers.isEqual(symbols, null)))
                {
                    throw new ArgumentsRequired((String)Helpers.add(this.id, " watchPositions() symbols is required")) ;
                }
                messageHash = Helpers.add(messageHash, Helpers.add("::", String.join((String)",", (java.util.List<String>)symbols)));
            }
            Object channel = Helpers.add(typeId, ".positions");
            Object subType = null;
            var subTypequeryVariable = this.handleSubTypeAndParams("watchPositions", market, query);
            subType = ((java.util.List<Object>) subTypequeryVariable).get(0);
            query = ((java.util.List<Object>) subTypequeryVariable).get(1);
            Object isInverse = (Helpers.isEqual(subType, "inverse"));
            Object url = this.getUrlByMarketType(type, isInverse);
            Client client = this.client(url);
            this.setPositionsCache(client, type, symbols);
            Object fetchPositionsSnapshot = this.handleOption("watchPositions", "fetchPositionsSnapshot", true);
            Object awaitPositionsSnapshot = this.handleOption("watchPositions", "awaitPositionsSnapshot", true);
            Object cache = this.safeValue(this.positions, type);
            if (Helpers.isTrue(Helpers.isTrue(Helpers.isTrue((Helpers.isEqual(fetchPositionsSnapshot, true))) && Helpers.isTrue((Helpers.isEqual(awaitPositionsSnapshot, true)))) && Helpers.isTrue((Helpers.isEqual(cache, null)))))
            {
                return client.future((String)Helpers.add(type, ":fetchPositionsSnapshot")).getFuture().join();
            }
            Object positions = (this.subscribePrivate(url, messageHash, payload, channel, query, true)).join();
            if (Helpers.isTrue(this.newUpdates))
            {
                return positions;
            }
            return this.filterBySymbolsSinceLimit(this.safeValue(this.positions, type), symbols, since, limit, true);
        }).thenApply(io.github.ccxt.TypedCores::toPositionList);

    }

    public void setPositionsCache(Client client, Object type, Object... optionalArgs)
    {
        Object symbols = Helpers.getArg(optionalArgs, 0, null);
        if (Helpers.isTrue(Helpers.isEqual(this.positions, null)))
        {
            this.positions = new java.util.HashMap<String, Object>() {{}};
        }
        if (Helpers.isTrue(Helpers.inOp(this.positions, type)))
        {
            return;
        }
        Object fetchPositionsSnapshot = this.handleOption("watchPositions", "fetchPositionsSnapshot", false);
        if (Helpers.isTrue(Helpers.isEqual(fetchPositionsSnapshot, true)))
        {
            Object messageHash = Helpers.add(type, ":fetchPositionsSnapshot");
            if (!Helpers.isTrue((Helpers.inOp(client.futures, messageHash))))
            {
                client.future((String)messageHash);
                this.spawn(() -> { try { this.loadPositionsSnapshot(client, messageHash, type); } catch(Exception _e) { throw new RuntimeException(_e); } });
            }
        } else
        {
            Helpers.addElementToObject(this.positions, type, new ArrayCache.ArrayCacheBySymbolBySide());
        }
    }

    public java.util.concurrent.CompletableFuture<Object> loadPositionsSnapshot(Client client, Object messageHash2, Object type2)
    {
        final Object messageHash3 = messageHash2;
        final Object type3 = type2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object messageHash = messageHash3;
            Object type = type3;
            final Object finalType = type;
            Object positions = io.github.ccxt.TypedCores.fromPositionList((this.fetchPositions((Object)(null), (Object)((Object) new java.util.HashMap<String, Object>() {{
                put( "type", finalType );
            }}))).join());
            Helpers.addElementToObject(this.positions, type, new ArrayCache.ArrayCacheBySymbolBySide());
            Object cache = Helpers.GetValue(this.positions, type);
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(positions)); i++)
            {
                Object position = Helpers.GetValue(positions, i);
                Object contracts = this.safeNumber(position, "contracts", 0);
                if (Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(contracts, null))) && Helpers.isTrue((Helpers.isGreaterThan(contracts, 0)))))
                {
                    Helpers.callDynamically(cache, "append", new Object[]{position});
                }
            }
            // don't remove the future from the .futures cache
            if (Helpers.isTrue(Helpers.inOp(client.futures, messageHash)))
            {
                io.github.ccxt.ws.Future future = (io.github.ccxt.ws.Future)Helpers.GetValue(client.futures, messageHash);
                ((io.github.ccxt.ws.Future)future).resolve(cache);
                client.resolve(cache, Helpers.add(type, ":position"));
            }
            return null;
        });

    }

    public void handlePositions(Client client, Object message)
    {
        //
        //    {
        //        time: 1693158497,
        //        time_ms: 1693158497204,
        //        channel: 'futures.positions',
        //        event: 'update',
        //        result: [{
        //            contract: 'XRP_USDT',
        //            cross_leverage_limit: 0,
        //            entry_price: 0.5253,
        //            history_pnl: 0,
        //            history_point: 0,
        //            last_close_pnl: 0,
        //            leverage: 0,
        //            leverage_max: 50,
        //            liq_price: 0.0361,
        //            maintenance_rate: 0.01,
        //            margin: 4.89609962852,
        //            mode: 'single',
        //            realised_pnl: -0.0026265,
        //            realised_point: 0,
        //            risk_limit: 500000,
        //            size: 1,
        //            time: 1693158497,
        //            time_ms: 1693158497195,
        //            update_id: 1,
        //            user: '10444586'
        //        }]
        //    }
        //
        Object type = this.getMarketTypeByUrl(client.url);
        Object data = this.safeValue(message, "result", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object cache = Helpers.GetValue(this.positions, type);
        Object newPositions = new java.util.ArrayList<Object>(java.util.Arrays.asList());
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(data)); i++)
        {
            Object rawPosition = Helpers.GetValue(data, i);
            Object position = this.parsePosition(rawPosition);
            Object symbol = this.safeString(position, "symbol");
            Object side = this.safeString(position, "side");
            // Control when position is closed no side is returned
            if (Helpers.isTrue(Helpers.isEqual(side, null)))
            {
                Object prevLongPosition = this.safeDict(cache, Helpers.add(symbol, "long"));
                if (Helpers.isTrue(!Helpers.isEqual(prevLongPosition, null)))
                {
                    Helpers.addElementToObject(position, "side", Helpers.GetValue(prevLongPosition, "side"));
                    ((java.util.List<Object>)newPositions).add(position);
                    Helpers.callDynamically(cache, "append", new Object[]{position});
                }
                Object prevShortPosition = this.safeDict(cache, Helpers.add(symbol, "short"));
                if (Helpers.isTrue(!Helpers.isEqual(prevShortPosition, null)))
                {
                    Helpers.addElementToObject(position, "side", Helpers.GetValue(prevShortPosition, "side"));
                    ((java.util.List<Object>)newPositions).add(position);
                    Helpers.callDynamically(cache, "append", new Object[]{position});
                }
                // if no prev position is found, default to long
                if (Helpers.isTrue(Helpers.isTrue(Helpers.isEqual(prevLongPosition, null)) && Helpers.isTrue(Helpers.isEqual(prevShortPosition, null))))
                {
                    Helpers.addElementToObject(position, "side", "long");
                    ((java.util.List<Object>)newPositions).add(position);
                    Helpers.callDynamically(cache, "append", new Object[]{position});
                }
            } else
            {
                ((java.util.List<Object>)newPositions).add(position);
                Helpers.callDynamically(cache, "append", new Object[]{position});
            }
        }
        Object messageHashes = this.findMessageHashes(client, Helpers.add(type, ":positions::"));
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(messageHashes)); i++)
        {
            Object messageHash = Helpers.GetValue(messageHashes, i);
            Object parts = Helpers.split(messageHash, "::");
            Object symbolsString = Helpers.GetValue(parts, 1);
            Object symbols = Helpers.split(symbolsString, ",");
            Object positions = this.filterByArray(newPositions, "symbol", symbols, false);
            if (!Helpers.isTrue(this.isEmpty(positions)))
            {
                client.resolve(positions, messageHash);
            }
        }
        client.resolve(newPositions, Helpers.add(type, ":positions"));
    }

    /**
     * @method
     * @name gate#watchOrders
     * @description watches information on multiple orders made by the user
     * @see https://www.gate.com/docs/developers/apiv4/ws/en/#orders-channel
     * @see https://www.gate.com/docs/developers/futures/ws/en/#orders-api
     * @see https://www.gate.com/docs/developers/delivery/ws/en/#orders-api
     * @see https://www.gate.com/docs/developers/options/ws/en/#orders-channel
     * @param {string} symbol unified market symbol of the market orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.type] spot, margin, swap, future, or option. Required if listening to all symbols.
     * @param {boolean} [params.isInverse] if future, listen to inverse or linear contracts
     * @param {boolean} [params.trigger] set to true to watch trigger orders, spot.priceorders and futures.autoorders channels, see https://github.com/ccxt/ccxt/issues/27202
     * @param {boolean} [params.stop] alias of params.trigger
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<java.util.List<io.github.ccxt.types.Order>> watchOrders(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object symbol = Helpers.getArg(optionalArgs, 0, null);
            Object since = Helpers.getArg(optionalArgs, 1, null);
            Object limit = Helpers.getArg(optionalArgs, 2, null);
            Object parameters = Helpers.getArg(optionalArgs, 3, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = null;
            if (Helpers.isTrue(!Helpers.isEqual(symbol, null)))
            {
                Object marketResolved = this.market(symbol);
                market = marketResolved;
                symbol = Helpers.GetValue(market, "symbol");
            }
            Object type = null;
            Object query = null;
            var typequeryVariable = this.handleMarketTypeAndParams("watchOrders", market, parameters);
            type = ((java.util.List<Object>) typequeryVariable).get(0);
            query = ((java.util.List<Object>) typequeryVariable).get(1);
            Object typeId = this.getSupportedMapping(type, new java.util.HashMap<String, Object>() {{
                put( "spot", "spot" );
                put( "margin", "spot" );
                put( "future", "futures" );
                put( "swap", "futures" );
                put( "option", "options" );
            }});
            Object isTrigger = false;
            var isTriggerqueryVariable = this.handleParamBool2(query, "trigger", "stop", false);
            isTrigger = ((java.util.List<Object>) isTriggerqueryVariable).get(0);
            query = ((java.util.List<Object>) isTriggerqueryVariable).get(1);
            if (Helpers.isTrue(Helpers.isTrue((Helpers.isEqual(isTrigger, true))) && Helpers.isTrue((Helpers.isEqual(typeId, "options")))))
            {
                throw new NotSupported((String)Helpers.add(this.id, " watchOrders() does not support trigger orders for options, see https://github.com/ccxt/ccxt/issues/27202")) ;
            }
            // gate pushes trigger orders on dedicated channels, spot.priceorders and futures.autoorders,
            // see https://github.com/ccxt/ccxt/issues/27202
            Object suffix = ".orders";
            if (Helpers.isTrue(Helpers.isEqual(isTrigger, true)))
            {
                suffix = ((Helpers.isTrue((Helpers.isEqual(typeId, "spot"))))) ? ".priceorders" : ".autoorders";
            }
            Object channel = Helpers.add(typeId, suffix);
            Object messageHash = ((Helpers.isTrue((Helpers.isEqual(isTrigger, true))))) ? "triggerOrders" : "orders";
            Object payload = new java.util.ArrayList<Object>(java.util.Arrays.asList(Helpers.add("!", "all")));
            if (Helpers.isTrue(!Helpers.isEqual(market, null)))
            {
                messageHash = Helpers.add(messageHash, Helpers.add(":", Helpers.GetValue(market, "id")));
                Object mid = Helpers.GetValue(market, "id");
                if (Helpers.isTrue(!Helpers.isEqual(mid, null)))
                {
                    payload = new java.util.ArrayList<Object>(java.util.Arrays.asList(mid));
                }
            }
            Object subType = null;
            var subTypequeryVariable = this.handleSubTypeAndParams("watchOrders", market, query);
            subType = ((java.util.List<Object>) subTypequeryVariable).get(0);
            query = ((java.util.List<Object>) subTypequeryVariable).get(1);
            Object isInverse = (Helpers.isEqual(subType, "inverse"));
            Object url = this.getUrlByMarketType(type, isInverse);
            // uid required for non spot markets
            Object requiresUid = (!Helpers.isEqual(type, "spot"));
            Object orders = (this.subscribePrivate(url, messageHash, payload, channel, query, requiresUid)).join();
            if (Helpers.isTrue(this.newUpdates))
            {
                limit = Helpers.callDynamically(orders, "getLimit", new Object[]{symbol, limit});
            }
            return this.filterBySinceLimit(orders, since, limit, "timestamp", true);
        }).thenApply(io.github.ccxt.TypedCores::toOrderList);

    }

    public void handleOrder(Client client, Object message)
    {
        //
        //     {
        //         "time": 1774613210,
        //         "time_ms": 1774613210392,
        //         "channel": "spot.orders",
        //         "event": "update",
        //         "result": [
        //             {
        //                 "id": "1036717689726",
        //                 "text": "apiv4",
        //                 "create_time": "1774613210",
        //                 "update_time": "1774613210",
        //                 "currency_pair": "BTC_USDT",
        //                 "type": "limit",
        //                 "account": "unified",
        //                 "side": "buy",
        //                 "amount": "0.1",
        //                 "price": "200",
        //                 "time_in_force": "gtc",
        //                 "left": "0.1",
        //                 "filled_amount": "0",
        //                 "filled_total": "0",
        //                 "avg_deal_price": "0",
        //                 "fee": "0",
        //                 "fee_currency": "BTC",
        //                 "point_fee": "0",
        //                 "gt_fee": "0",
        //                 "rebated_fee": "0",
        //                 "rebated_fee_currency": "BTC",
        //                 "create_time_ms": "1774613210391",
        //                 "update_time_ms": "1774613210391",
        //                 "user": 10406147,
        //                 "event": "put",
        //                 "stp_id": 0,
        //                 "stp_act": "-",
        //                 "finish_as": "open",
        //                 "biz_info": "ch:ccxt",
        //                 "amend_text": "-"
        //             }
        //         ]
        //     }
        //
        Object orders = this.safeValue(message, "result", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object channel = this.safeString(message, "channel", "");
        Object isTrigger = Helpers.isTrue((Helpers.isGreaterThanOrEqual(Helpers.getIndexOf(channel, "autoorders"), 0))) || Helpers.isTrue((Helpers.isGreaterThanOrEqual(Helpers.getIndexOf(channel, "priceorders"), 0)));
        Object hashPrefix = ((Helpers.isTrue(isTrigger))) ? "triggerOrders" : "orders";
        Object limit = this.safeInteger(this.options, "ordersLimit", 1000);
        if (Helpers.isTrue(Helpers.isEqual(this.orders, null)))
        {
            this.orders = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
            this.triggerOrders = new ArrayCache.ArrayCacheBySymbolById(((Number)limit).intValue());
        }
        Object stored = ((Helpers.isTrue(isTrigger))) ? this.triggerOrders : this.orders;
        Object marketIds = new java.util.HashMap<String, Object>() {{}};
        Object parsedOrders = this.parseOrders(orders);
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(parsedOrders)); i++)
        {
            Object parsed = Helpers.GetValue(parsedOrders, i);
            // inject order status
            Object info = this.safeValue(parsed, "info");
            Object eventVar = this.safeString(info, "event");
            if (Helpers.isTrue(Helpers.isTrue(Helpers.isEqual(eventVar, "put")) || Helpers.isTrue(Helpers.isEqual(eventVar, "update"))))
            {
                Helpers.addElementToObject(parsed, "status", "open");
            } else if (Helpers.isTrue(Helpers.isEqual(eventVar, "finish")))
            {
                Object status = this.safeString(parsed, "status");
                if (Helpers.isTrue(Helpers.isEqual(status, null)))
                {
                    Object left = this.safeInteger(info, "left");
                    Helpers.addElementToObject(parsed, "status", ((Helpers.isTrue((Helpers.isEqual(left, 0))))) ? "closed" : "canceled");
                }
            }
            Helpers.callDynamically(stored, "append", new Object[]{parsed});
            Object symbol = Helpers.GetValue(parsed, "symbol");
            Object market = this.market(symbol);
            if (Helpers.isTrue(!Helpers.isEqual(Helpers.GetValue(market, "id"), null)))
            {
                Helpers.addElementToObject(marketIds, Helpers.GetValue(market, "id"), true);
            }
        }
        Object keys = Helpers.objectKeys(marketIds);
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(keys)); i++)
        {
            Object messageHash = Helpers.add(Helpers.add(hashPrefix, ":"), Helpers.GetValue(keys, i));
            client.resolve(stored, messageHash);
        }
        client.resolve(stored, hashPrefix);
    }

