    /**
     * @method
     * @name gate#watchMyLiquidationsForSymbols
     * @description watch the private liquidations of a trading pair
     * @see https://www.gate.io/docs/developers/futures/ws/en/#liquidates-api
     * @see https://www.gate.io/docs/developers/delivery/ws/en/#liquidates-api
     * @see https://www.gate.io/docs/developers/options/ws/en/#liquidates-channel
     * @param {string[]} symbols unified CCXT market symbols
     * @param {int} [since] the earliest time in ms to fetch liquidations for
     * @param {int} [limit] the maximum number of liquidation structures to retrieve
     * @param {object} [params] exchange specific parameters for the gate api endpoint
     * @returns {object} an array of [liquidation structures]{@link https://github.com/ccxt/ccxt/wiki/Manual#liquidation-structure}
     */
    public java.util.concurrent.CompletableFuture<java.util.List<io.github.ccxt.types.Liquidation>> watchMyLiquidationsForSymbols(Object symbols2, Object... optionalArgs)
    {
        final Object symbols3 = symbols2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object symbols = symbols3;
            Object since = Helpers.getArg(optionalArgs, 0, null);
            Object limit = Helpers.getArg(optionalArgs, 1, null);
            Object parameters = Helpers.getArg(optionalArgs, 2, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            symbols = this.marketSymbols(symbols, null, true, true);
            Object market = this.getMarketFromSymbols(symbols);
            Object type = null;
            Object query = null;
            var typequeryVariable = this.handleMarketTypeAndParams("watchMyLiquidationsForSymbols", market, parameters);
            type = ((java.util.List<Object>) typequeryVariable).get(0);
            query = ((java.util.List<Object>) typequeryVariable).get(1);
            Object typeId = this.getSupportedMapping(type, new java.util.HashMap<String, Object>() {{
                put( "future", "futures" );
                put( "swap", "futures" );
                put( "option", "options" );
            }});
            Object subType = null;
            var subTypequeryVariable = this.handleSubTypeAndParams("watchMyLiquidationsForSymbols", market, query);
            subType = ((java.util.List<Object>) subTypequeryVariable).get(0);
            query = ((java.util.List<Object>) subTypequeryVariable).get(1);
            Object isInverse = (Helpers.isEqual(subType, "inverse"));
            Object url = this.getUrlByMarketType(type, isInverse);
            Object payload = new java.util.ArrayList<Object>(java.util.Arrays.asList());
            Object messageHash = "";
            if (Helpers.isTrue(this.isEmpty(symbols)))
            {
                if (Helpers.isTrue(Helpers.isTrue(!Helpers.isEqual(typeId, "futures")) && !Helpers.isTrue(isInverse)))
                {
                    throw new BadRequest((String)Helpers.add(this.id, " watchMyLiquidationsForSymbols() does not support listening to all symbols, you must call watchMyLiquidations() instead for each symbol you wish to watch.")) ;
                }
                messageHash = "myLiquidations";
                ((java.util.List<Object>)payload).add("!all");
            } else
            {
                Object symbolsLength = Helpers.getArrayLength(symbols);
                if (Helpers.isTrue(!Helpers.isEqual(symbolsLength, 1)))
                {
                    throw new BadRequest((String)Helpers.add(this.id, " watchMyLiquidationsForSymbols() only allows one symbol at a time. To listen to several symbols call watchMyLiquidationsForSymbols() several times.")) ;
                }
                messageHash = Helpers.add("myLiquidations::", Helpers.GetValue(symbols, 0));
                ((java.util.List<Object>)payload).add(Helpers.GetValue(market, "id"));
            }
            Object channel = Helpers.add(typeId, ".liquidates");
            Object newLiquidations = (this.subscribePrivate(url, messageHash, payload, channel, query, true)).join();
            if (Helpers.isTrue(this.newUpdates))
            {
                return newLiquidations;
            }
            return this.filterBySymbolsSinceLimit(this.liquidations, symbols, since, limit, true);
        }).thenApply(io.github.ccxt.TypedCores::toLiquidationList);

    }

    public void handleLiquidation(Client client, Object message)
    {
        //
        // future / delivery
        //     {
        //         "channel":"futures.liquidates",
        //         "event":"update",
        //         "time":1541505434,
        //         "time_ms":1541505434123,
        //         "result":[
        //            {
        //               "entry_price":209,
        //               "fill_price":215.1,
        //               "left":0,
        //               "leverage":0.0,
        //               "liq_price":213,
        //               "margin":0.007816722941,
        //               "mark_price":213,
        //               "order_id":4093362,
        //               "order_price":215.1,
        //               "size":-124,
        //               "time":1541486601,
        //               "time_ms":1541486601123,
        //               "contract":"BTC_USD",
        //               "user":"1040xxxx"
        //            }
        //         ]
        //     }
        // option
        //    {
        //        "channel":"options.liquidates",
        //        "event":"update",
        //        "time":1630654851,
        //        "result":[
        //           {
        //              "user":"1xxxx",
        //              "init_margin":1190,
        //              "maint_margin":1042.5,
        //              "order_margin":0,
        //              "time":1639051907,
        //              "time_ms":1639051907000
        //           }
        //        ]
        //    }
        //
        Object rawLiquidations = this.safeList(message, "result", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
        Object newLiquidations = new java.util.ArrayList<Object>(java.util.Arrays.asList());
        if (Helpers.isTrue(Helpers.isEqual(this.liquidations, null)))
        {
            Object limit = this.safeInteger(this.options, "liquidationsLimit", 1000);
            this.liquidations = new ArrayCache(((Number)limit).intValue());
        }
        Object cache = this.liquidations;
        for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(rawLiquidations)); i++)
        {
            Object rawLiquidation = Helpers.GetValue(rawLiquidations, i);
            Object liquidation = this.parseWsLiquidation(rawLiquidation);
            Helpers.callDynamically(cache, "append", new Object[]{liquidation});
            Object symbol = this.safeString(liquidation, "symbol");
            Object symbolLiquidations = this.safeValue(cache, symbol, new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            client.resolve(symbolLiquidations, Helpers.add("myLiquidations::", symbol));
        }
        client.resolve(newLiquidations, "myLiquidations");
    }

    public Object parseWsLiquidation(Object liquidation, Object... optionalArgs)
    {
        //
        // future / delivery
        //    {
        //        "entry_price": 209,
        //        "fill_price": 215.1,
        //        "left": 0,
        //        "leverage": 0.0,
        //        "liq_price": 213,
        //        "margin": 0.007816722941,
        //        "mark_price": 213,
        //        "order_id": 4093362,
        //        "order_price": 215.1,
        //        "size": -124,
        //        "time": 1541486601,
        //        "time_ms": 1541486601123,
        //        "contract": "BTC_USD",
        //        "user": "1040xxxx"
        //    }
        // option
        //    {
        //        "user": "1xxxx",
        //        "init_margin": 1190,
        //        "maint_margin": 1042.5,
        //        "order_margin": 0,
        //        "time": 1639051907,
        //        "time_ms": 1639051907000
        //    }
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object marketId = this.safeString(liquidation, "contract");
        market = this.safeMarket(marketId, market);
        Object timestamp = this.safeInteger(liquidation, "time_ms");
        Object originalSize = this.safeString(liquidation, "size");
        Object left = this.safeString(liquidation, "left");
        Object amount = Precise.stringAbs(Precise.stringSub(originalSize, left));
        final Object finalMarket = market;
        return this.safeLiquidation(new java.util.HashMap<String, Object>() {{
            put( "info", liquidation );
            put( "symbol", Gate.this.safeSymbol(marketId, finalMarket) );
            put( "contracts", Gate.this.parseNumber(amount) );
            put( "contractSize", Gate.this.safeNumber(finalMarket, "contractSize") );
            put( "price", Gate.this.safeNumber(liquidation, "fill_price") );
            put( "baseValue", null );
            put( "quoteValue", null );
            put( "timestamp", timestamp );
            put( "datetime", Gate.this.iso8601(timestamp) );
        }});
    }

    public Object handleErrorMessage(Client client, Object message)
    {
        //
        //    {
        //        "time": 1647274664,
        //        "channel": "futures.orders",
        //        "event": "subscribe",
        //        "error": { code: 2, message: "unknown contract BTC_USDT_20220318" },
        //    }
        //    {
        //      "time": 1647276473,
        //      "channel": "futures.orders",
        //      "event": "subscribe",
        //      "error": {
        //        "code": 4,
        //        "message": "{"label":"INVALID_KEY","message":"Invalid key provided"}\n"
        //      },
        //      "result": null
        //    }
        //    {
        //       header: {
        //         response_time: '1718551891329',
        //         status: '400',
        //         channel: 'spot.order_place',
        //         event: 'api',
        //         client_id: '81.34.68.6-0xc16375e2c0',
        //         conn_id: '9539116e0e09678f'
        //       },
        //       data: { errs: { label: 'AUTHENTICATION_FAILED', message: 'Not login' } },
        //       request_id: '10406147'
        //     }
        //     {
        //         "time": 1739853211,
        //         "time_ms": 1739853211201,
        //         "id": 1,
        //         "conn_id": "62f2c1dabbe186d7",
        //         "trace_id": "cdb02a8c0b61086b2fe6f8fad2f98c54",
        //         "channel": "spot.trades",
        //         "event": "subscribe",
        //         "payload": [
        //             "LUNARLENS_USDT",
        //             "ETH_USDT"
        //         ],
        //         "error": {
        //             "code": 2,
        //             "message": "unknown currency pair: LUNARLENS_USDT"
        //         },
        //         "result": {
        //             "status": "fail"
        //         },
        //         "requestId": "cdb02a8c0b61086b2fe6f8fad2f98c54"
        //     }
        //
        Object data = this.safeDict(message, "data");
        Object errs = this.safeDict(data, "errs");
        Object error = this.safeDict(message, "error", errs);
        Object code = this.safeString2(error, "code", "label");
        Object id = this.safeStringN(message, new java.util.ArrayList<Object>(java.util.Arrays.asList("id", "requestId", "request_id")));
        if (Helpers.isTrue(!Helpers.isEqual(error, null)))
        {
            Object messageHash = this.safeString(client.subscriptions, id);
            try
            {
                this.throwExactlyMatchedException(Helpers.GetValue(Helpers.GetValue(this.exceptions, "ws"), "exact"), code, this.json(message));
                this.throwExactlyMatchedException(Helpers.GetValue(this.exceptions, "exact"), code, this.json(errs));
                Object errorMessage = this.safeString(error, "message", this.safeString(errs, "message"));
                this.throwBroadlyMatchedException(Helpers.GetValue(Helpers.GetValue(this.exceptions, "ws"), "broad"), errorMessage, this.json(message));
                throw new ExchangeError((String)this.json(message)) ;
            } catch(Exception e)
            {
                client.reject(e, messageHash);
                if (Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(messageHash, null))) && Helpers.isTrue((Helpers.inOp(client.subscriptions, messageHash)))))
                {
                    ((java.util.Map<String,Object>)client.subscriptions).remove((String)messageHash);
                }
                // remove subscriptions for watchSymbols
                Object channel = ((String)this.safeString(message, "channel"));
                if (Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(channel, null))) && Helpers.isTrue((Helpers.isGreaterThan(Helpers.getIndexOf(channel, "."), 0)))))
                {
                    Object parsedChannel = Helpers.split(channel, ".");
                    Object payload = this.safeList(message, "payload", new java.util.ArrayList<Object>(java.util.Arrays.asList()));
                    for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(payload)); i++)
                    {
                        Object marketType = ((Helpers.isTrue(Helpers.isEqual(Helpers.GetValue(parsedChannel, 0), "futures")))) ? "swap" : Helpers.GetValue(parsedChannel, 0);
                        Object symbol = this.safeSymbol(Helpers.GetValue(payload, i), null, "_", marketType);
                        Object messageHashSymbol = Helpers.add(Helpers.add(Helpers.GetValue(parsedChannel, 1), ":"), symbol);
                        if (Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(messageHashSymbol, null))) && Helpers.isTrue((Helpers.inOp(client.subscriptions, messageHashSymbol)))))
                        {
                            ((java.util.Map<String,Object>)client.subscriptions).remove((String)messageHashSymbol);
                        }
                    }
                }
            }
            if (Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(id, null))) && Helpers.isTrue((Helpers.inOp(client.subscriptions, id)))))
            {
                ((java.util.Map<String,Object>)client.subscriptions).remove((String)id);
            }
            return true;
        }
        return false;
    }

